'use strict';

/* eslint n/no-unsupported-features/es-builtins: ["error", {"version": ">=12.0.0"}] */

/* eslint n/no-unsupported-features/node-builtins: ["error", {"version": ">=12.0.0"}] */


// MODULES //

var tape = require( 'tape' );
var run = require( './helpers.js' );
var main = require( './../lib/main.js' );
var dpbtf2 = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual(typeof main, 'function');

	t.end();
});

tape( 'dpbtf2: public main6 and ndarray7', function test( t ) {
	t.strictEqual( typeof dpbtf2, 'function' );
	t.strictEqual( dpbtf2.length, 6 );
	t.strictEqual( dpbtf2.ndarray.length, 7 );
	t.end();
});
tape( 'dpbtf2: pure JavaScript reference, band equations and mutation', function test( t ) {
	run( t, main );
	t.end();
});
tape( 'dpbtf2: selected public reference, band equations and mutation', function test( t ) {
	run( t, dpbtf2 );
	t.end();
});
